  kind: "info",
  guideSlug: "corner-tv-placement",
  guideTitle: "Corner TV Placement: When It Works and When It Does Not",
  metaTitle: "Corner TV Placement: When It Works",
  metaDescription: "Putting a TV in a corner can free wall space or ruin viewing. Learn the viewing angles, corner stands versus corner mounts and how to deal with window glare.",
  heroImage: "/images/articles/cornertv-1960s-room-tv-window.webp",
